@Transactional
public void processPayment(String idempotencyKey, PaymentRequest request) {
    if (repository.existsByIdempotencyKey(idempotencyKey)) {
        return; // Already processed, return cached result or success
    }

    // Execute business logic
    paymentService.execute(request);

    // Record the key to prevent future duplicates
    repository.save(new ProcessedRequest(idempotencyKey, LocalDateTime.now()));
}
